WITH base AS (SELECT id, order_id, method, amount, paid_at, CASE WHEN amount >= 1400 THEN 'High' WHEN amount >= 520 THEN 'Medium' ELSE 'Low' END AS amount_level, CASE WHEN amount >= 1340 THEN 'High' WHEN amount >= 600 THEN 'Medium' ELSE 'Low' END AS amount_tier FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-06-14 09:00:00') AND order_id IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN amount >= 1530 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, burst_id, MAX(paid_at) AS ended_at, ROUND(AVG(amount), 2) AS avg_amount, GROUPING(CASE WHEN amount >= 1530 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN amount >= 1530 THEN 'LARGE' ELSE 'SMALL' END, burst_id), (CASE WHEN amount >= 1530 THEN 'LARGE' ELSE 'SMALL' END), ()) HAVING avg_amount > 0
